'use client';
import { CaretLeftIcon, FileIcon, PaperclipIcon, PlusIcon, UploadIcon, XIcon } from '@phosphor-icons/react';
import { useTranslations } from 'next-intl';
import { type ChangeEvent, useCallback, useEffect, useRef, useState } from 'react';
import { colors, spacing, typography } from 'up-design-tokens';

import { AgentInput } from '@/app/components/AgentPanel/AgentInput/AgentInput';
import { AgentInputWithPlaceholder } from '@/app/components/AgentPanel/AgentInput/AgentInputWithPlaceholder';
import { Button } from '@/app/components/Button/Button';
import { ChatConversation, CourseArtifactSheet, CourseCreationChatSidebar } from '@/app/components/CourseCreationChat';
import { CourseCardCompact } from '@/app/components/CourseGrid';
import { DragOverlay } from '@/app/components/DragOverlay/DragOverlay';
import { Greeting } from '@/app/components/Greeting/Greeting';
import { TopNav } from '@/app/components/TopNav/TopNav';
import { useAlert } from '@/app/context/AlertContext';
import { useUser } from '@/app/context/UserContext';
import { useApiWithTenantAuthZ, useNavigation, usePromptStarters } from '@/app/hooks';
import { useCourseCreationChat } from '@/app/hooks/useCourseCreationChat';
import { Course } from '@/app/types';
import {
    ALLOWED_CONTEXT_FILE_ACCEPT,
    ALLOWED_CONTEXT_FILE_FORMAT_NAMES,
    splitFilesByAllowedContextType,
} from '@/app/utils/contextFileTypes';
import { isCreditError } from '@/app/utils/isCreditError';

import { PromptStarters } from './PromptStarters';

const promptStartersHeading = 'Try a prompt starter';

function fileStageKey(file: File): string {
    return `${file.name}-${file.size}-${file.lastModified}`;
}

export function CourseCreateChat() {
    const t = useTranslations('getStarted.idle');
    const chat = useCourseCreationChat();
    const navigate = useNavigation();
    const { showAlert } = useAlert();
    const { selectedTenant } = useUser();
    const { starters, loading: promptStartersLoading } = usePromptStarters();

    const [started, setStarted] = useState(false);
    const [composerValue, setComposerValue] = useState('');
    const [stagedFiles, setStagedFiles] = useState<File[]>([]);
    const [artifactOpen, setArtifactOpen] = useState(false);
    const [isAttaching, setIsAttaching] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const pdfInputRef = useRef<HTMLInputElement>(null);
    const hasTriggeredCreation = useRef(false);

    const hasComposerInput = composerValue.trim().length > 0;

    const {
        data: coursesData,
        loading: coursesLoading,
        doFetch: fetchCourses,
    } = useApiWithTenantAuthZ<{ courses: Course[] }>('/courses');

    useEffect(() => {
        void fetchCourses().catch(() => undefined);
    }, [fetchCourses]);

    const handleFinalize = useCallback(async () => {
        if (hasTriggeredCreation.current) return;
        hasTriggeredCreation.current = true;

        try {
            const courseId = await chat.finalizeDiscovery();
            navigate.toMasterbrainLevels(courseId, { llmEnabled: false });
        } catch (err) {
            if (isCreditError(err)) return;
            hasTriggeredCreation.current = false;
            showAlert({
                type: 'error',
                title: 'Error creating course',
                message: 'Failed to create the course. Please try again.',
            });
        }
    }, [chat, navigate, showAlert]);

    const handleComposerSend = useCallback(
        (text: string) => {
            const trimmed = text.trim();
            if (!trimmed) return;
            setComposerValue('');
            chat.sendMessage(trimmed);
        },
        [chat],
    );

    const handlePdfSelected = useCallback(
        async (event: ChangeEvent<HTMLInputElement>) => {
            const file = event.target.files?.[0];
            event.target.value = '';
            if (!file) return;

            setIsAttaching(true);
            try {
                await chat.attachFileSource(file);
                showAlert({ type: 'success', title: 'PDF added', variant: 'brief' });
            } catch {
                showAlert({
                    type: 'error',
                    title: 'Could not attach PDF',
                    message: 'Failed to add the PDF. Please try again.',
                });
            } finally {
                setIsAttaching(false);
            }
        },
        [chat, showAlert],
    );

    const handleDroppedFiles = useCallback(
        async (files: File[]) => {
            try {
                await chat.openSourcesCard();
                const { failedFileNames } = await chat.uploadContextFiles(files);
                if (failedFileNames.length > 0) {
                    showAlert({
                        type: 'error',
                        title: 'Some materials could not be uploaded',
                        message: failedFileNames.join(', '),
                    });
                }
            } catch {
                showAlert({
                    type: 'error',
                    title: 'Error preparing sources',
                    message: 'Failed to prepare the course draft. Please try again.',
                });
            }
        },
        [chat, showAlert],
    );

    const handleFileDrop = useCallback(
        (files: File[]) => {
            if (started && (chat.isResponding || chat.isCreatingDraft)) return;

            const { accepted, rejected } = splitFilesByAllowedContextType(files);
            if (rejected.length > 0) {
                showAlert({
                    type: 'error',
                    title: 'Unsupported file type',
                    message: `Supported formats: ${ALLOWED_CONTEXT_FILE_FORMAT_NAMES}.`,
                });
            }
            if (accepted.length === 0) return;

            if (!started) {
                setStagedFiles((prev) => {
                    const existingKeys = new Set(prev.map(fileStageKey));
                    return [...prev, ...accepted.filter((file) => !existingKeys.has(fileStageKey(file)))];
                });
                return;
            }

            void handleDroppedFiles(accepted);
        },
        [started, chat.isResponding, chat.isCreatingDraft, showAlert, handleDroppedFiles],
    );

    const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return;
        const files = Array.from(e.target.files);
        e.target.value = '';
        handleFileDrop(files);
    };

    const handleRemoveStagedFile = (key: string) => {
        setStagedFiles((prev) => prev.filter((file) => fileStageKey(file) !== key));
    };

    const startChat = useCallback(
        (text: string) => {
            setStarted(true);
            setComposerValue('');
            if (stagedFiles.length > 0) {
                void chat
                    .startWithMaterials(text, stagedFiles)
                    .then(({ failedFileNames }) => {
                        setStagedFiles([]);
                        if (failedFileNames.length === 0) return;
                        showAlert({
                            type: 'error',
                            title: 'Some materials could not be uploaded',
                            message: failedFileNames.join(', '),
                        });
                    })
                    .catch((err) => {
                        // Files stay staged so backing out to the welcome screen can retry them.
                        if (isCreditError(err)) return;
                        showAlert({
                            type: 'error',
                            title: 'Error uploading materials',
                            message: 'Failed to prepare the course materials. Please try again.',
                        });
                    });
                return;
            }

            if (text) chat.sendMessage(text);
        },
        [chat, stagedFiles, showAlert],
    );

    const handleWelcomeSend = (text: string) => startChat(text.trim());

    const handleStartWithMaterials = () => startChat(composerValue.trim());

    const handleOpenSourcesCard = useCallback(async () => {
        try {
            await chat.openSourcesCard();
        } catch {
            showAlert({
                type: 'error',
                title: 'Error preparing sources',
                message: 'Failed to prepare the course draft. Please try again.',
            });
        }
    }, [chat, showAlert]);

    const handleResetSession = useCallback(
        async (exit: boolean) => {
            try {
                await chat.discardDraft();
            } catch {
                showAlert({
                    type: 'error',
                    title: 'Could not discard draft',
                    message: "The unsaved draft won't appear in your courses.",
                    autoDismiss: true,
                });
            } finally {
                chat.resetSession();
