const ensureDraftCourse = useCallback(async (): Promise<CourseUuid> => {
    if (draftCourseIdRef.current) return draftCourseIdRef.current;

    setIsCreatingDraft(true);
    try {
        const draft = await decodeCourseUuidResponse(
            await fetchWithTenantAuth(COURSES_PATH, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: 'draft', name: t('untitledCourse') }),
            }),
        );
        setDraftCourseId(draft.uuid);
        draftCourseIdRef.current = draft.uuid;
        return draft.uuid;
    } finally {
        setIsCreatingDraft(false);
    }
}, [fetchWithTenantAuth, t]);

const refreshSources = useCallback(async () => {
    const currentDraftCourseId = draftCourseIdRef.current;
    if (!currentDraftCourseId) return;

    const response = await decodeSourceDigestsResponse(
        await fetchWithTenantAuth(`/courses/${currentDraftCourseId}/context/digests`),
    );
    const nextSources = [...response.sources];
    setSources(nextSources);
    sourcesRef.current = nextSources;
}, [fetchWithTenantAuth]);

const waitForSourceDigests = useCallback(
    async (
        pendingIds: string[] | undefined,
        epoch: number,
        timeoutMs = SOURCE_DIGEST_TIMEOUT_MS,
    ): Promise<DigestWaitOutcome> => {
        if (sessionEpochRef.current !== epoch) return 'cancelled';

        // Refresh once so we (a) settle the race where a PDF finished before we
        // subscribed and (b) can derive the watched set for the `undefined` case.
        try {
            await refreshSources();
        } catch {
            // A transient refresh failure should not cancel the material-backed turn.
        }
        if (sessionEpochRef.current !== epoch) return 'cancelled';

        const watchedIds =
            pendingIds ??
            sourcesRef.current
                .filter((digest) => digest.type === 'file' && digest.status === 'processing')
                .map((digest) => digest.sourceId);

        if (areSourceDigestsSettled(sourcesRef.current, watchedIds)) return 'settled';

        const remaining = new Set(
            watchedIds.filter((sourceId) => {
                const digest = sourcesRef.current.find((candidate) => candidate.sourceId === sourceId);
                return digest === undefined || digest.status === 'processing';
            }),
        );
        if (remaining.size === 0) return 'settled';

        return new Promise<DigestWaitOutcome>((resolve) => {
            let settled = false;

            // `finish` reads the handles below; it only runs asynchronously,
            // after all three consts have been initialized.
            const finish = (outcome: DigestWaitOutcome) => {
                if (settled) return;
                settled = true;
                unsubscribe();
                clearTimeout(timeout);
                clearInterval(epochInterval);
                resolve(outcome);
            };

            const unsubscribe = subscribeRef.current('pdf_processing_progress', (event) => {
                if (event.type !== 'pdf_processing_progress') return;
                const { data } = event;
                if (draftCourseIdRef.current && data.courseUuid !== draftCourseIdRef.current) return;
                if (!remaining.has(data.contextFileUuid)) return;
                if (data.job.status !== 'COMPLETED' && data.job.status !== 'FAILED') return;

                remaining.delete(data.contextFileUuid);
                if (remaining.size > 0) return;

                // Refresh so the follow-up turn sends the freshly-ready digests.
                refreshSources()
                    .catch(() => undefined)
                    .finally(() => finish('settled'));
            });

            const timeout = setTimeout(() => finish('timeout'), timeoutMs);
            const epochInterval = setInterval(() => {
                if (sessionEpochRef.current !== epoch) finish('cancelled');
            }, 1_000);
        });
    },
    [refreshSources],
);

const uploadContextFiles = useCallback(
    async (
        files: File[],
    ): Promise<{
        uploadedIds: string[];
        pendingDigestIds: string[];
        failedFileNames: string[];
    }> => {
        const courseId = await ensureDraftCourse();
        const outcomes = await Promise.all(
            files.map(async (file) => {
                try {
                    const body = new FormData();
                    body.append('file', file);
                    const uploaded = await decodeContextFileUploadResponse(
                        await fetchWithTenantAuth(`/courses/${courseId}/context/files`, {
                            method: 'POST',
                            body,
                            signal: AbortSignal.timeout(CONTEXT_FILE_UPLOAD_TIMEOUT_MS),
                        }),
                    );
                    return { file, uploaded };
                } catch {
                    return { file };
                }
            }),
        );
        const successfulUploads = outcomes.flatMap((outcome) =>
            outcome.uploaded ? [{ ...outcome.uploaded, name: outcome.uploaded.name || outcome.file.name }] : [],
        );

        setReadyItems((prev) => {
            const existingFiles = prev
                .filter((item) => item.type === 'file')
                .map((item) => ({ uuid: item.id, name: item.name }));
            return mergeReadyItems(prev, [...existingFiles, ...successfulUploads], 'file', (file) => file.name);
        });

        return {
            uploadedIds: successfulUploads.map((upload) => upload.uuid),
            pendingDigestIds: successfulUploads
                .filter((upload) => upload.processingJob !== undefined)
                .map((upload) => upload.uuid),
            failedFileNames: outcomes.flatMap((outcome) => (outcome.uploaded ? [] : [outcome.file.name])),
        };
    },

