const startWithMaterials = useCallback(
    async (text: string, files: File[]): Promise<MaterialsUploadResult> => {
        if (isResponding) return { failedFileNames: [] };

        const epoch = sessionEpochRef.current;
        const trimmed = text.trim();
        setError(null);
        if (trimmed) {
            setMessages((prev) => [
                ...prev,
                {
                    id: crypto.randomUUID(),
                    sender: 'user',
                    text: trimmed,
                    timestamp: new Date(),
                },
            ]);
        }
        setIsResponding(true);
        setStreaming(READING_MATERIALS_STREAMING);

        let sendStarted = false;
        try {
            const uploadResult = await uploadContextFiles(files);
            if (uploadResult.uploadedIds.length === 0 && !trimmed) {
                return { failedFileNames: uploadResult.failedFileNames };
            }

            const waitOutcome = await waitForSourceDigests(uploadResult.pendingDigestIds, epoch);
            if (waitOutcome === 'cancelled') {
                return { failedFileNames: uploadResult.failedFileNames };
            }
            sendStarted = true;
            await performSend(trimmed || "I've added my materials.", undefined, { hideUserBubble: true });
            return { failedFileNames: uploadResult.failedFileNames };
        } catch (cause) {
            const errorText = cause instanceof Error ? cause.message : 'Failed to prepare your materials.';
            setError(errorText);
            throw cause;
        } finally {
            // If the session was reset mid-flight, resetSession already cleared
            // this state — and a newer turn may own it now, so leave it alone.
            if (!sendStarted && sessionEpochRef.current === epoch) {
                setStreaming(null);
                setIsResponding(false);
            }
        }
    },
    [isResponding, performSend, uploadContextFiles, waitForSourceDigests],
);

