'use client';
import { CheckCircleIcon, PencilSimpleIcon } from '@phosphor-icons/react';
import { useState } from 'react';
import type { AddedItem, CourseUuid } from 'up-types';

import AddContent from '@/app/components/AddContent/AddContent';
import { Button } from '@/app/components/Button/Button';
import type { FileItem, LinkItem, TextItem } from '@/app/types/course';

export type InlineAddSourcesProps = {
    courseId: CourseUuid;
    readyItems: AddedItem[];
    onFilesChange: (files: FileItem[]) => void;
    onLinksChange: (links: LinkItem[]) => void;
    onTextsChange: (texts: TextItem[]) => void;
    onRemoveItem: (item: AddedItem) => void;
    onError: (message: string, type: string) => void;
    onAddSuccess: (type: 'file' | 'url' | 'text') => void;
    /** Concludes with the attached sources and asks the agent to continue. */
    onDone: () => void;
    /** Concludes with no materials and asks the agent to continue. */
    onSkip: () => void;
};

/**
 * Inline, in-conversation card for attaching course materials. Starts in a `collecting`
 * state wrapping the shared `AddContent`, then collapses to a concluded summary once the
 * user is done so the agent can ground the outline in the attached sources.
 */
export function InlineAddSources({
    courseId,
    readyItems,
    onFilesChange,
    onLinksChange,
    onTextsChange,
    onRemoveItem,
    onError,
    onAddSuccess,
    onDone,
    onSkip,
}: InlineAddSourcesProps) {
    const [phase, setPhase] = useState<'collecting' | 'concluded'>('collecting');

    const handleDone = () => {
        setPhase('concluded');
        onDone();
    };

    const handleSkip = () => {
        setPhase('concluded');
        onSkip();
    };

    const handleEdit = () => setPhase('collecting');

    if (phase === 'concluded') {
        const hasSources = readyItems.length > 0;
        return (
            <div className="mt-3 w-full max-w-3xl rounded-2xl border border-gray-200 bg-white p-4">
                <div className="flex items-center justify-between gap-3">
                    <div className="flex min-w-0 items-center gap-2">
                        <CheckCircleIcon size={18} weight="thin" className="shrink-0 text-gray-700" />
                        <span className="truncate text-sm font-medium text-gray-900">
                            {hasSources
                                ? `${readyItems.length} ${readyItems.length === 1 ? 'source' : 'sources'} added`
                                : 'Continuing without materials'}
                        </span>
                    </div>
                    <Button
                        type="button"
                        variant="grey-outline"
                        size="small"
                        icon={<PencilSimpleIcon size={14} weight="thin" />}
                        label="Edit"
                        onClick={handleEdit}
                        className="rounded-full! min-w-0! px-3!"
                    />
                </div>
                {hasSources && (
                    <p className="mt-2 truncate text-xs text-gray-500">
                        {readyItems.map((item) => item.name).join(' · ')}
                    </p>
                )}
            </div>
        );
    }

    return (
        <div className="mt-3 w-full max-w-3xl rounded-2xl border border-gray-200 bg-white p-4">
            <p className="mb-3 text-sm font-medium text-gray-900">Add your data</p>
            <AddContent
                variant="modal"
                courseId={courseId}
                readyItems={readyItems}
                onFileChange={onFilesChange}
                onLinkChange={onLinksChange}
                onTextChange={onTextsChange}
                onRemoveItem={onRemoveItem}
                onError={onError}
                onAddSuccess={onAddSuccess}
            />
            <div className="mt-4 flex items-center justify-end gap-2">
                <Button
                    type="button"
                    variant="grey-outline"
                    label="Skip"
                    onClick={handleSkip}
                    className="rounded-full! min-w-0! px-5!"
                />
                <Button
                    type="button"
                    variant="primary"
                    label="Done — use these"
                    onClick={handleDone}
                    disabled={readyItems.length === 0}
                    className="rounded-full! min-w-0! px-5!"
                />
            </div>
        </div>
    );
}

