'use client';
import { CaretRightIcon, MagnifyingGlassIcon, PaperclipIcon, SparkleIcon } from '@phosphor-icons/react';
import { type ReactNode, type RefObject, useCallback, useEffect, useRef, useState } from 'react';
import { colors, radii, spacing, typography } from 'up-design-tokens';
import type { CourseArtifact } from 'up-types';

import { Button } from '@/app/components/Button/Button';
import Markdown from '@/app/components/Markdown/Markdown';
import type { ChatCreationMessage, StreamingAgentTurn } from '@/app/hooks/useCourseCreationChat';
import { parseThinkingTitles } from '@/app/utils/parseThinkingTitles';

import { CourseArtifactChip } from './CourseArtifactChip';
import { CourseOutlinePreview } from './CourseOutlinePreview';
import { InlineAddSources, type InlineAddSourcesProps } from './InlineAddSources';
import { InlineWebSources, type InlineWebSourcesProps } from './InlineWebSources';

type CourseCreationOptionIntent = 'add_sources' | 'search_web' | 'confirm_course_creation';

const OPTION_ICON_BY_INTENT: Record<CourseCreationOptionIntent, ReactNode> = {
    add_sources: <PaperclipIcon weight="thin" className="h-4 w-4" />,
    search_web: <MagnifyingGlassIcon weight="thin" className="h-4 w-4" />,
    confirm_course_creation: <SparkleIcon weight="thin" className="h-4 w-4" />,
};

function getOptionIcon(intent: CourseCreationOptionIntent | undefined) {
    return intent === undefined ? undefined : OPTION_ICON_BY_INTENT[intent];
}

function getOptionButtonClass(intent: CourseCreationOptionIntent | undefined, disabled: boolean) {
    const base =
        'rounded-full! h-auto! min-w-0! px-5! py-2! text-base font-regular transition-colors disabled:cursor-default disabled:opacity-50';

    if (intent === 'add_sources') {
        return `${base} border-green-300! bg-green-100! text-green-700! ${
            disabled ? '' : 'hover:border-green-500! hover:bg-green-300!'
        }`;
    }

    if (intent === 'search_web') {
        return `${base} border-blue-200! bg-blue-50! text-blue-700! ${
            disabled ? '' : 'hover:border-blue-700! hover:bg-blue-200!'
        }`;
    }

    if (intent === 'confirm_course_creation') {
        return `${base} border-gray-900! bg-gray-900! text-white! ${disabled ? '' : 'hover:bg-gray-700!'}`;
    }

    return `${base} border-gray-300! bg-white! text-gray-900! hover:border-gray-500! ${
        disabled ? 'hover:border-gray-300!' : ''
    }`;
}

function customButtonClass(disabled: boolean) {
    return `rounded-full! h-auto! min-w-0! border-dashed! border-gray-300! bg-white! px-5! py-2! text-sm font-medium text-gray-500 transition-colors hover:border-gray-500! hover:text-gray-900! disabled:cursor-default disabled:opacity-50 ${
        disabled ? 'hover:border-gray-300! hover:text-gray-500!' : ''
    }`;
}

function CustomOptionTextField({
    value,
    onChange,
    onSubmit,
    disabled,
    inputRef,
}: {
    value: string;
    onChange: (value: string) => void;
    onSubmit: () => void;
    disabled: boolean;
    inputRef: RefObject<HTMLInputElement | null>;
}) {
    return (
        <form
            onSubmit={(e) => {
                e.preventDefault();
                onSubmit();
            }}
            className="flex items-center gap-2"
        >
            <input
                ref={inputRef}
                type="text"
                value={value}
                onChange={(e) => onChange(e.target.value)}
                disabled={disabled}
                placeholder="Type your answer..."
                aria-label="Type your answer"
                maxLength={500}
                className="rounded-full border border-gray-300 bg-white px-4 py-2 text-sm text-gray-900 outline-hidden transition-colors placeholder:text-gray-400 focus:border-gray-500 disabled:cursor-not-allowed disabled:opacity-50"
            />
            <Button
                type="submit"
                variant="secondary"
                size="small"
                label="Send"
                disabled={disabled || !value.trim()}
                className="rounded-full! h-auto! min-w-0! px-4! py-2!"
            />
        </form>
    );
}

function OptionsWithCustomInput({
    options,
    onSelect,
    onAddSources,
    disabled,
}: {
    options: Array<{ label: string; value: string; intent?: CourseCreationOptionIntent }>;
    onSelect: (value: string, label?: string) => void;
    onAddSources: () => void;
    disabled: boolean;
}) {
    const [showInput, setShowInput] = useState(false);
    const [customText, setCustomText] = useState('');
    const [submitted, setSubmitted] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const controlsDisabled = disabled || submitted;

    const handleSelect = (option: { label: string; value: string; intent?: CourseCreationOptionIntent }) => {
        if (controlsDisabled) return;
