12	export class NoFileUploadedError extends Data.TaggedError('NoFileUploadedError')<{ message: string }> {}
13	
14	const CreateCourseContextFileParamsSchema = Schema.Struct({
15	    courseUuid: CourseUuidSchema,
16	});
17	
18	const CreateCourseContextFileBodySchema = Schema.Struct({
19	    name: Schema.optional(Schema.String),
20	    description: Schema.optional(Schema.String),
21	    metadata: Schema.optional(Schema.Any),
22	    sortOrder: Schema.optional(Schema.NumberFromString),
23	});
24	
25	export interface CreateCourseContextFileResult {
26	    uuid: string;
27	    name?: string;
28	    description?: string;
29	    processingJob?: {
30	        uuid: string;
31	        type: string;
32	        status: string;
33	    };
34	}
