36	export const program = Effect.gen(function* () {
37	    const { req } = yield* ExpressContext;
38	    const courseAssetsService = yield* CourseAssetsService;
39	    const tenantFileService = yield* TenantFileService;
40	    const jobService = yield* JobService;
41	    const courseEventService = yield* CourseEventService;
42	
43	    const { tenantUuid, tenantUserUuid } = req.tenantUserMember;
44	
45	    const { courseUuid } = yield* Schema.decodeUnknown(CreateCourseContextFileParamsSchema)(req.params);
46	    const contextFields = yield* Schema.decodeUnknown(CreateCourseContextFileBodySchema)(req.body);
47	
48	    if (!req.file) {
49	        return yield* Effect.fail(new NoFileUploadedError({ message: 'No file uploaded' }));
50	    }
51	
52	    const file = yield* Schema.decodeUnknown(MultipartFileSchema)(req.file);
53	
54	    yield* courseAssetsService.checkAllowedFileType(file.mimetype);
55	
56	    const uploadResult = yield* tenantFileService.saveUploadedFile({
57	        tenantUuid,
58	        file,
59	    });
60	
61	    const contextResult = yield* courseAssetsService.createCourseContextFile(
62	        {
63	            courseUuid,
64	            fileUuid: uploadResult.fileUuid,
65	            name: contextFields.name,
66	            description: contextFields.description,
67	            metadata: contextFields.metadata,
68	            sortOrder: contextFields.sortOrder,
69	            mimeType: file.mimetype,
70	        },
71	        tenantUuid,
72	    );
73	
74	    // For PDF files, create a job and publish async processing event
75	    if (file.mimetype === 'application/pdf') {
76	        const job = yield* jobService.createJob({
77	            type: 'PDF_PROCESSING',
78	            status: 'CREATED',
79	            externalReference: contextResult.uuid,
80	            statusMessage: `Processing PDF file: ${file.originalname}`,
81	            metadata: {
82	                fileUuid: uploadResult.fileUuid,
83	                contextFileUuid: contextResult.uuid,
84	                courseUuid,
85	                originalFilename: file.originalname,
86	            },
87	        });
88	
89	        yield* courseEventService.publishPdfProcessingRequested({
90	            fileUuid: uploadResult.fileUuid,
91	            contextFileUuid: contextResult.uuid,
92	            courseUuid,
93	            tenantUuid,
94	            tenantUserUuid,
95	            jobUuid: job.uuid,
96	        });
97	
98	        yield* Effect.logInfo(`Created PDF processing job ${job.uuid} for context file ${contextResult.uuid}`);
99	
100	        // Return context file with processing job info
101	        return {
102	            ...contextResult,
103	            processingJob: {
104	                uuid: job.uuid,
105	                type: job.type,
106	                status: job.status,
107	            },
108	        } as CreateCourseContextFileResult;
109	    }
110	
111	    // Non-PDF files return immediately without processing job
112	    return contextResult as CreateCourseContextFileResult;
113	});
