import { Cause, Data, Effect, Layer, Match, Schema } from 'effect';
import { CourseUuidSchema } from 'up-types';

import { CourseAssetsDbRepositoryLive, CourseAssetsService } from '../course-assets';
import { CourseSourceIngestionService } from '../course-source-rag';
import { CourseEventService, CourseEventsServiceLayer } from '../courses/course-events.service';
import { ExpressContext } from '../http-server/express';
import { JobDbRepositoryLive, JobService, JobServiceLive } from '../jobs';
import { MultipartFileSchema, TenantFileService, TenantFileServiceLayer } from '../tenant-files';
import { buildApiResponse } from '../utils/api-response';

export class NoFileUploadedError extends Data.TaggedError('NoFileUploadedError')<{ message: string }> {}

const CreateCourseContextFileParamsSchema = Schema.Struct({
    courseUuid: CourseUuidSchema,
});

const CreateCourseContextFileBodySchema = Schema.Struct({
    name: Schema.optional(Schema.String),
    description: Schema.optional(Schema.String),
    metadata: Schema.optional(Schema.Any),
    sortOrder: Schema.optional(Schema.NumberFromString),
});

export interface CreateCourseContextFileResult {
    uuid: string;
    name?: string;
    description?: string;
    processingJob?: {
        uuid: string;
        type: string;
        status: string;
    };
}

export const program = Effect.gen(function* () {
    const { req } = yield* ExpressContext;
    const courseAssetsService = yield* CourseAssetsService;
    const tenantFileService = yield* TenantFileService;
    const jobService = yield* JobService;
    const courseEventService = yield* CourseEventService;

    const { tenantUuid, tenantUserUuid } = req.tenantUserMember;

    const { courseUuid } = yield* Schema.decodeUnknown(CreateCourseContextFileParamsSchema)(req.params);
    const contextFields = yield* Schema.decodeUnknown(CreateCourseContextFileBodySchema)(req.body);

    if (!req.file) {
        return yield* Effect.fail(new NoFileUploadedError({ message: 'No file uploaded' }));
    }

    const file = yield* Schema.decodeUnknown(MultipartFileSchema)(req.file);

    yield* courseAssetsService.checkAllowedFileType(file.mimetype);

    const uploadResult = yield* tenantFileService.saveUploadedFile({
        tenantUuid,
        file,
    });

    const contextResult = yield* courseAssetsService.createCourseContextFile(
        {
            courseUuid,
            fileUuid: uploadResult.fileUuid,
            name: contextFields.name,
            description: contextFields.description,
            metadata: contextFields.metadata,
            sortOrder: contextFields.sortOrder,
            mimeType: file.mimetype,
        },
        tenantUuid,
    );

    // For PDF files, create a job and publish async processing event
    if (file.mimetype === 'application/pdf') {
        const job = yield* jobService.createJob({
            type: 'PDF_PROCESSING',
            status: 'CREATED',
            externalReference: contextResult.uuid,
            statusMessage: `Processing PDF file: ${file.originalname}`,
            metadata: {
                fileUuid: uploadResult.fileUuid,
                contextFileUuid: contextResult.uuid,
                courseUuid,
                originalFilename: file.originalname,
            },
        });

        yield* courseEventService.publishPdfProcessingRequested({
            fileUuid: uploadResult.fileUuid,
            contextFileUuid: contextResult.uuid,
            courseUuid,
            tenantUuid,
            tenantUserUuid,
            jobUuid: job.uuid,
        });

        yield* Effect.logInfo(`Created PDF processing job ${job.uuid} for context file ${contextResult.uuid}`);

        // Return context file with processing job info
        return {
            ...contextResult,
            processingJob: {
                uuid: job.uuid,
                type: job.type,
                status: job.status,
            },
        } as CreateCourseContextFileResult;
    }

    // Non-PDF files return immediately without processing job
    return contextResult as CreateCourseContextFileResult;
});

export const createCourseContextFileController = Effect.gen(function* () {
    const { req, res } = yield* ExpressContext;
    const { correlationId } = req;
    const { tenantUserUuid } = req.tenantUserMember;
    const { errorResponse } = buildApiResponse('Create course context file', req);

    return yield* program.pipe(
        Effect.tap(() => Effect.logInfo('Created course context file')),
        Effect.tapErrorCause((cause) => Effect.logError(Cause.pretty(cause))),

        // deps
        Effect.provide(
            CourseAssetsService.DefaultWithoutDependencies.pipe(
                Layer.provide(CourseAssetsDbRepositoryLive),
                Layer.provide(CourseSourceIngestionService.Default),
                Layer.provideMerge(TenantFileServiceLayer),
            ),
        ),
        Effect.provide(JobServiceLive.pipe(Layer.provide(JobDbRepositoryLive))),
        Effect.provide(CourseEventsServiceLayer),

        // log/trace metadata
        Effect.annotateLogs({ op: 'createCourseContextFileController', correlationId, tenantUserUuid }),
        Effect.withSpan('createCourseContextFileController', { attributes: { correlationId, tenantUserUuid } }),

        // HTTP response handling
        Effect.matchEffect({
            onSuccess: (result) => Effect.sync(() => res.status(200).json(result)),
            onFailure: (err) =>
                Match.value(err).pipe(
                    Match.tag('NoFileUploadedError', (e) =>
                        Effect.sync(() => res.status(400).json(errorResponse(e.message))),
                    ),
                    Match.tag('ParseError', (e) => Effect.sync(() => res.status(400).json(errorResponse(e.message)))),
                    Match.tag('InvalidFileTypeError', (e) =>
                        Effect.sync(() => res.status(400).json(errorResponse(e.message))),
                    ),
                    Match.tag('TenantFileServiceError', () =>
                        Effect.sync(() => res.status(500).json(errorResponse('Failed to save file to storage'))),
                    ),
                    Match.tag('ContextCreateError', () =>
                        Effect.sync(() => res.status(500).json(errorResponse('Failed to create context file'))),
                    ),
                    Match.tag('JobServiceError', () =>
                        Effect.sync(() => res.status(500).json(errorResponse('Failed to create processing job'))),
                    ),
                    Match.tag('CourseEventServiceError', () =>
                        Effect.sync(() => res.status(500).json(errorResponse('Failed to queue PDF processing'))),
                    ),
                    Match.orElse(() =>
                        Effect.sync(() => res.status(500).json(errorResponse('Failed to process file upload'))),
                    ),
                ),
        }),
    );
});

