import { Cause, Effect, Layer, Schema } from 'effect';
import type { Job, TenantMember } from 'up-types';

import { CourseAssetsDbRepositoryLive, CourseAssetsService } from '../course-assets';
import { CourseSourceIngestionService } from '../course-source-rag';
import { COURSE_EVENTS, PdfProcessingRequestedEvent, PdfProcessingRequestedEventSchema } from '../courses/events';
import { SqlLive } from '../database/sql';
import { JobDbRepositoryLive, JobService, JobServiceLive } from '../jobs';
import { KafkaMessage } from '../kafka';
import { StructuredLogger } from '../logger';
import { PdfProcessingService } from '../pdf-processing';
import { SourceDigestService } from '../source-digest';
import { broadcastToTenantUsers } from '../sse';
import { StorageService, TenantFileRepository, TenantFileServiceLive } from '../tenant-files';
import { TenantUserService, TenantUserServiceLive } from '../tenants_users/tenant-user-service';

type BroadcastProgressFn = (
    message: string,
    job: Job,
    extra?: { progress?: number; extractedImages?: number; totalPages?: number },
) => Effect.Effect<void>;

class PdfProcessingMessageParseError extends Schema.TaggedError<PdfProcessingMessageParseError>()(
    'PdfProcessingMessageParseError',
    { message: Schema.String, cause: Schema.optional(Schema.Unknown) },
) {}

const parseMessage = (message: KafkaMessage) =>
    Effect.gen(function* () {
        if (!message.value) {
            return yield* new PdfProcessingMessageParseError({ message: 'Received message with no value' });
        }
        const parsed = yield* Effect.try({
            try: () => JSON.parse(message.value!) as unknown,
            catch: (error) =>
                new PdfProcessingMessageParseError({ message: 'Failed to parse message JSON', cause: error }),
        });
        return yield* Schema.decodeUnknown(PdfProcessingRequestedEventSchema)(parsed);
    });

const createBroadcastProgress =
    (tenantMembers: readonly TenantMember[], event: PdfProcessingRequestedEvent): BroadcastProgressFn =>
    (message, job, extra) =>
        broadcastToTenantUsers([...tenantMembers], {
            type: 'pdf_processing_progress' as const,
            data: {
                message,
                contextFileUuid: event.contextFileUuid,
                courseUuid: event.courseUuid,
                tenantUuid: event.tenantUuid,
                job,
                timestamp: new Date(),
                progress: extra?.progress,
                extractedImages: extra?.extractedImages,
                totalPages: extra?.totalPages,
            },
        });

const buildLogAttributes = (message: KafkaMessage) => ({
    op: 'pdfProcessingRequested',
    'message.topic': message.topic,
    'message.partition': message.partition,
    'message.offset': message.offset,
    'message.key': message.key,
});

export const pdfProcessingRequestedCore = (message: KafkaMessage) =>
    Effect.gen(function* () {
        const jobService = yield* JobService;
        const tenantUserService = yield* TenantUserService;
        const pdfProcessingService = yield* PdfProcessingService;

        yield* Effect.logInfo(`Processing PDF processing request for message: ${message.key}`);

        const event = yield* parseMessage(message);
        const tenantMembers = yield* tenantUserService.getTenantMembers(event.tenantUuid);
        const broadcastProgress = createBroadcastProgress(tenantMembers, event);

        const { job } = yield* jobService
            .executeJob(
                event.jobUuid,
                (job) =>
                    Effect.gen(function* () {
                        yield* Effect.logInfo(`Starting PDF processing for file: ${event.fileUuid}`);
                        yield* broadcastProgress('Starting PDF processing', job);

                        const result = yield* pdfProcessingService.processPdf(
                            event.fileUuid,
                            event.tenantUuid,
                            event.courseUuid,
                            event.contextFileUuid,
                        );

                        yield* Effect.logInfo(
                            `PDF processing completed: ${result.pageCount} pages, ${result.extractedImages.length} images, ${result.extractedText.length} chars`,
                        );

                        yield* broadcastProgress('PDF processing completed', job, {
                            progress: 100,
                            extractedImages: result.extractedImages.length,
                            totalPages: result.pageCount,
                        });

                        return {
                            metadata: {
                                fileUuid: event.fileUuid,
                                contextFileUuid: event.contextFileUuid,
                                courseUuid: event.courseUuid,
                                pageCount: result.pageCount,
                                extractedImages: result.extractedImages.length,
                                textLength: result.extractedText.length,
                                timestamp: new Date(),
                            },
                        };
                    }),
                {
                    retry: {
                        topic: COURSE_EVENTS.PDF_PROCESSING_REQUESTED,
                        payload: event,
                    },
                },
            )
            .pipe(
                Effect.catchTag('JobExecutionError', (error) =>
                    Effect.gen(function* () {
                        yield* broadcastProgress(`PDF processing failed: ${error.message}`, error.job);
                        return yield* error;
                    }),
                ),
            );

        yield* broadcastProgress('PDF processed successfully', job, { progress: 100 });
    }).pipe(
        Effect.tap(() => Effect.logInfo('PDF processing request processed successfully')),
        Effect.tapErrorCause((cause) => Effect.logError(Cause.pretty(cause))),
        Effect.annotateLogs(buildLogAttributes(message)),
        Effect.withSpan('pdfProcessingRequested', { attributes: buildLogAttributes(message) }),
        Effect.catchAll((error) => Effect.log(`Error processing PDF: ${error.message || error}`)),
    );

export const pdfProcessingRequested = (message: KafkaMessage) =>
    pdfProcessingRequestedCore(message).pipe(
        Effect.provide(
            Layer.mergeAll(
                TenantUserServiceLive,
                JobServiceLive.pipe(Layer.provide(JobDbRepositoryLive)),
                PdfProcessingService.Default.pipe(
                    Layer.provide(SourceDigestService.Default),
                    Layer.provide(CourseSourceIngestionService.Default),
                ),
                StructuredLogger,
            ).pipe(
                Layer.provideMerge(CourseAssetsService.Default.pipe(Layer.provide(CourseAssetsDbRepositoryLive))),
                Layer.provideMerge(TenantFileServiceLive.pipe(Layer.provide(TenantFileRepository.Default))),
                Layer.provideMerge(StorageService.Default),
                Layer.provideMerge(SqlLive),
            ),
        ),
    );

