1	import { LanguageModel } from '@effect/ai';
2	import { AnthropicLanguageModel } from '@effect/ai-anthropic/index';
3	import { GoogleLanguageModel } from '@effect/ai-google';
4	import { OpenAiLanguageModel } from '@effect/ai-openai';
5	import { Effect, ExecutionPlan } from 'effect';
6	
7	import { makeStep } from '../ai-engine/llm/fallback';
8	import { AiClientsLive } from '../ai-engine/llm/providers/clients';
9	import { SourceDigestError } from './errors';
10	import { buildSummarizePrompt, type SourceDigestSourceType } from './prompt';
11	import { SourceDigestDraftSchema, sourceDigestObjectName } from './schemas';
12	
13	const MAX_INPUT_CHARS = 24_000;
14	const MAX_SUMMARY_CHARS = 520;
15	const MAX_TOPICS = 6;
16	
17	const summarizeDigestPlan = (config: { maxTokens: number; temperature: number }) =>
18	    ExecutionPlan.make(
19	        makeStep(
20	            'google:gemini-2.5-flash',
21	            GoogleLanguageModel.model('gemini-2.5-flash', {
22	                toolConfig: {},
23	                generationConfig: { maxOutputTokens: config.maxTokens, temperature: config.temperature },
24	            }),
25	        ),
26	        makeStep(
27	            'openai:gpt-5-mini',
28	            OpenAiLanguageModel.model('gpt-5-mini', {
29	                max_output_tokens: config.maxTokens,
30	            }),
31	        ),
32	        makeStep(
33	            'anthropic:claude-sonnet-4-6',
34	            AnthropicLanguageModel.model('claude-sonnet-4-6', {
35	                max_tokens: config.maxTokens,
36	                temperature: config.temperature,
37	            }),
38	        ),
39	    );
40	
41	export class SourceDigestService extends Effect.Service<SourceDigestService>()(
42	    'uniplay/modules/source-digest/service',
43	    {
44	        effect: Effect.sync(() => {
45	            const summarizeText = Effect.fn('SourceDigestService.summarizeText')(function* (params: {
46	                name: string;
47	                type: SourceDigestSourceType;
48	                text: string;
49	            }) {
50	                const prompt = buildSummarizePrompt({
51	                    name: params.name,
52	                    type: params.type,
53	                    text: params.text.slice(0, MAX_INPUT_CHARS),
54	                    maxSummaryChars: MAX_SUMMARY_CHARS,
55	                    maxTopics: MAX_TOPICS,
56	                });
57	
58	                return yield* LanguageModel.generateObject({
59	                    prompt,
60	                    schema: SourceDigestDraftSchema,
61	                    objectName: sourceDigestObjectName,
62	                }).pipe(
63	                    Effect.map((response) => response.value),
64	                    Effect.withExecutionPlan(summarizeDigestPlan({ maxTokens: 2048, temperature: 0.2 })),
65	                    Effect.provide(AiClientsLive),
66	                    Effect.mapError(
67	                        (cause) => new SourceDigestError({ message: 'Failed to summarize source text', cause }),
68	                    ),
69	                );
70	            });
71	
72	            return { summarizeText };
73	        }),
74	    },
75	) {}
