import { LanguageModel } from '@effect/ai';
import { AnthropicLanguageModel } from '@effect/ai-anthropic/index';
import { GoogleLanguageModel } from '@effect/ai-google';
import { OpenAiLanguageModel } from '@effect/ai-openai';
import { Effect, ExecutionPlan } from 'effect';

import { makeStep } from '../ai-engine/llm/fallback';
import { AiClientsLive } from '../ai-engine/llm/providers/clients';
import { SourceDigestError } from './errors';
import { buildSummarizePrompt, type SourceDigestSourceType } from './prompt';
import { SourceDigestDraftSchema, sourceDigestObjectName } from './schemas';

const MAX_INPUT_CHARS = 24_000;
const MAX_SUMMARY_CHARS = 520;
const MAX_TOPICS = 6;

const summarizeDigestPlan = (config: { maxTokens: number; temperature: number }) =>
    ExecutionPlan.make(
        makeStep(
            'google:gemini-2.5-flash',
            GoogleLanguageModel.model('gemini-2.5-flash', {
                toolConfig: {},
                generationConfig: { maxOutputTokens: config.maxTokens, temperature: config.temperature },
            }),
        ),
        makeStep(
            'openai:gpt-5-mini',
            OpenAiLanguageModel.model('gpt-5-mini', {
                max_output_tokens: config.maxTokens,
            }),
        ),
        makeStep(
            'anthropic:claude-sonnet-4-6',
            AnthropicLanguageModel.model('claude-sonnet-4-6', {
                max_tokens: config.maxTokens,
                temperature: config.temperature,
            }),
        ),
    );

export class SourceDigestService extends Effect.Service<SourceDigestService>()(
    'uniplay/modules/source-digest/service',
    {
        effect: Effect.sync(() => {
            const summarizeText = Effect.fn('SourceDigestService.summarizeText')(function* (params: {
                name: string;
                type: SourceDigestSourceType;
                text: string;
            }) {
                const prompt = buildSummarizePrompt({
                    name: params.name,
                    type: params.type,
                    text: params.text.slice(0, MAX_INPUT_CHARS),
                    maxSummaryChars: MAX_SUMMARY_CHARS,
                    maxTopics: MAX_TOPICS,
                });

                return yield* LanguageModel.generateObject({
                    prompt,
                    schema: SourceDigestDraftSchema,
                    objectName: sourceDigestObjectName,
                }).pipe(
                    Effect.map((response) => response.value),
                    Effect.withExecutionPlan(summarizeDigestPlan({ maxTokens: 2048, temperature: 0.2 })),
                    Effect.provide(AiClientsLive),
                    Effect.mapError(
                        (cause) => new SourceDigestError({ message: 'Failed to summarize source text', cause }),
                    ),
                );
            });

            return { summarizeText };
        }),
    },
) {}

