export interface ChatConversationProps {
    messages: ChatCreationMessage[];
    isResponding: boolean;
    streaming: StreamingAgentTurn | null;
    error: string | null;
    onSelectOption: (value: string, displayText?: string) => void;
    onAddSources: () => void;
    /** Opens the full-course side sheet; the `artifact` chip renders only when both are provided. */
    onOpenArtifact: () => void;
    /** Live course artifact rendered by every `artifact` chip (shared state, not per-message snapshots). */
    artifact?: CourseArtifact;
    /** Handlers + draft state for the inline add-data card; absent until a draft course exists. */
    sourcesCard?: InlineAddSourcesProps;
    /** Handlers for the inline web-search-results card; the per-message `sources` are injected here. */
    webSourcesCard?: Omit<InlineWebSourcesProps, 'sources'>;
}

export function ChatConversation({
    messages,
    isResponding,
    streaming,
    error,
    onSelectOption,
    onAddSources,
    onOpenArtifact,
    artifact,
    sourcesCard,
    webSourcesCard,
}: ChatConversationProps) {
    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const timeout = setTimeout(() => {
            messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
        return () => clearTimeout(timeout);
    }, [messages, isResponding, streaming?.message, streaming?.thinking]);

    const findLastAgentMessageIndex = useCallback(() => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].sender === 'agent') return i;
        }
        return -1;
    }, [messages]);

    const renderAgentMessage = (msg: ChatCreationMessage, index: number) => {
        const isLatestAgentMessage = index === findLastAgentMessageIndex();
        const hasText = msg.text.trim().length > 0;
        const thinkingTitles = msg.thinkingTitles ?? [];

        return (
            <div className="flex flex-col items-start gap-2">
                <MasterbrainHeader />
                <ThinkingTimeline titles={thinkingTitles} />

                {hasText && (
                    <div className="max-w-3xl text-sm leading-relaxed text-gray-900 [&_p]:mb-0 [&_p+p]:mt-2">
                        <Markdown>{msg.text}</Markdown>
                    </div>
                )}

                {msg.outline && msg.outline.length > 0 && <CourseOutlinePreview outline={msg.outline} />}

                {msg.options && msg.options.length > 0 && (
                    <OptionsWithCustomInput
                        options={[...msg.options]}
                        onSelect={(value, label) => onSelectOption(value, label)}
                        onAddSources={onAddSources}
                        disabled={!isLatestAgentMessage || isResponding}
                    />
                )}
            </div>
        );
    };

    const renderMessage = (msg: ChatCreationMessage, index: number) => {
        if (msg.kind === 'add_sources') {
            return sourcesCard ? <InlineAddSources {...sourcesCard} /> : null;
        }
        if (msg.kind === 'web_sources') {
            return webSourcesCard ? <InlineWebSources {...webSourcesCard} sources={msg.webSources ?? []} /> : null;
        }

